arguments.sql_query:
SELECT COUNT(*) AS als_patients, MIN(index_date) AS earliest, MAX(index_date) AS latest
FROM (
  SELECT co.person_id, MIN(co.condition_start_date) AS index_date
  FROM omop.condition_occurrence co
  WHERE co.condition_concept_id IN (
    SELECT descendant_concept_id FROM omop.concept_ancestor WHERE ancestor_concept_id = 373182
  )
  GROUP BY co.person_id
) als_dx;

SELECT po.person_id, po.procedure_date, po.procedure_concept_id
FROM omop.procedure_occurrence po
WHERE po.procedure_concept_id IN (
  SELECT descendant_concept_id FROM omop.concept_ancestor
  WHERE ancestor_concept_id IN (4230167, 4072503, 2008007, 2008008, 2008009, 44782563)
);
